// Filter rows: active cases, hearing is tomorrow, not yet alerted
const items = $input.all();
const today = new Date();
today.setHours(0,0,0,0);
const tomorrow = new Date(today);
tomorrow.setDate(today.getDate() + 1);
const tomorrowStr = tomorrow.toISOString().slice(0,10);

const filtered = items.filter(item => {
  const status = (item.json['status'] || '').trim().toLowerCase();
  const nextDate = (item.json['next_hearing_date'] || '').toString().slice(0,10);
  const alerted = (item.json['alert_sent'] || '').trim().toLowerCase();
  return status === 'active' && nextDate === tomorrowStr && alerted !== 'yes';
});

return filtered;

