// Telegram sends multiple photo sizes; pick the largest (last item)
const message = $input.first().json.message;
if (!message || !message.photo || message.photo.length === 0) {
  throw new Error('No photo found in this message. Please send a photo of the document.');
}
const largest = message.photo[message.photo.length - 1];
return [{ json: { file_id: largest.file_id, chat_id: message.chat.id } }];

// Convert downloaded binary image to base64 for the vision API
const binary = $input.first().binary.data;
const base64 = binary.data;
const mimeType = binary.mimeType || 'image/jpeg';
return [{
  json: {
    base64Image: base64,
    mimeType: mimeType,
    chat_id: $('Get Largest Photo ID').first().json.chat_id
  }
}];

