// Parse the AI's JSON response, with basic error handling
const raw = $input.first().json.choices[0].message.content;
let parsed;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Could not parse AI response as JSON: ' + raw);
}
parsed.status = 'Active';
parsed.alert_sent = 'No';
parsed.chat_id = $('Convert to Base64').first().json.chat_id;
return [{ json: parsed }];

// Build a quick summary: total active cases + cases due in the next 7 days
const items = $input.all();
const today = new Date();
today.setHours(0,0,0,0);
const weekAhead = new Date(today);
weekAhead.setDate(today.getDate() + 7);

const active = items.filter(i => (i.json.status || '').toLowerCase() === 'active');
const dueThisWeek = active.filter(i => {
  const d = new Date(i.json.next_hearing_date);
  return d >= today && d <= weekAhead;
});

const newCase = $('Parse AI Response').first().json;

return [{
  json: {
    chat_id: newCase.chat_id,
    newCase,
    totalActive: active.length,
    dueThisWeekCount: dueThisWeek.length,
    dueThisWeekList: dueThisWeek.map(i => `${i.json.case_number} - ${i.json.next_hearing_date}`).join('\n')
  }
}];

